inputs.expression:
(
    /* Rename the mitre analysis key to mitre */
    $renameMitre := function($obj) {
        $obj ? $obj ~> | $ | { "mitre": $."ai-mitre-analysis" }, ["ai-mitre-analysis"] | : {}
    };

    /* Get raw results */
    $case_analysis := variables.CASE_Analysis ;
    $mitre_analysis := variables.MITRE_Analysis ;

    /* Format results for merge */
    $case_results := ($case_analysis and $type($case_analysis) = "object") ? $case_analysis
    : ($case_analysis and $type($case_analysis) = "array" and $type($case_analysis[0]) = "object") ? $case_analysis[0]
    : {} ;

    $mitre_results := ($mitre_analysis and $type($mitre_analysis) = "object") ? $mitre_analysis
    : ($mitre_analysis and $type($mitre_analysis) = "array" and $type($mitre_analysis[0]) = "object") ? $mitre_analysis[0]
    : {} ;

    /*Renamed MITRE Analysis Result"*/
    $mitre_renamed := {"ai-mitre-analysis":$renameMitre($mitre_results)};

    /* Merge results */
    $merge([$case_results, $mitre_renamed,{"analysis-agent-start-time": Analysis_Start_Time},{"ai-evidence": inputs.Evidence},{"mitre-techniques-changed":"False"}])
)
